```yaml
name: Deploy to GitHub Pages

on:
  push:
    branches:
      - main
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: "pages"
  cancel-in-progress: false

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Create index.html
        run: |
          mkdir -p docs
          cat > docs/index.html << 'EOF'
          <!DOCTYPE html>
          <html lang="en">
          <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Dr. Manhattan</title>
            <style>
              :root {
                --bg-color: #050510;
                --card-bg: #0a0a1a;
                --text-color: #e0e0ff;
                --accent-color: #00f0ff;
                --accent-glow: rgba(0, 240, 255, 0.5);
                --secondary-color: #7000ff;
              }

              * {
                box-sizing: border-box;
                margin: 0;
                padding: 0;
              }

              body {
                font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                background-color: var(--bg-color);
                color: var(--text-color);
                line-height: 1.6;
                overflow-x: hidden;
              }

              /* Cosmic Background Animation */
              body::before {
                content: '';
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: radial-gradient(circle at 50% 50%, #1a1a3a 0%, #050510 100%);
                z-index: -1;
              }

              .container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 2rem;
              }

              header {
                text-align: center;
                padding: 4rem 0;
                position: relative;
              }

              h1 {
                font-size: 3.5rem;
                margin-bottom: 1rem;
                background: linear-gradient(90deg, var(--accent-color), var(--secondary-color));
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                text-shadow: 0 0 20px var(--accent-glow);
              }

              .subtitle {
                font-size: 1.2rem;
                color: #8888aa;
                margin-bottom: 2rem;
              }

              /* Install Command */
              .install-box {
                background: var(--card-bg);
                border: 1px solid var(--accent-color);
                border-radius: 8px;
                padding: 1rem;
                display: inline-flex;
                align-items: center;
                gap: 1rem;
                box-shadow: 0 0 15px var(--accent-glow);
                margin-bottom: 3rem;
                position: relative;
              }

              .code {
                font-family: 'Courier New', Courier, monospace;
                color: var(--accent-color);
                font-size: 1.1rem;
              }

              .copy-btn {
                background: transparent;
                border: 1px solid var(--accent-color);
                color: var(--accent-color);
                padding: 0.5rem 1rem;
                border-radius: 4px;
                cursor: pointer;
                transition: all 0.3s ease;
              }

              .copy-btn:hover {
                background: var(--accent-color);
                color: var(--bg-color);
                box-shadow: 0 0 10px var(--accent-glow);
              }

              /* Feature Cards */
              .features {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 2rem;
                margin-bottom: 4rem;
              }

              .card {
                background: var(--card-bg);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 12px;
                padding: 2rem;
                transition: transform 0.3s ease, box-shadow 0.3s ease;
                position: relative;
                overflow: hidden;
              }

              .card:hover {
                transform: translateY(-5px);
                box-shadow: 0 10px 30px rgba(0, 240, 255, 0.2);
                border-color: var(--accent-color);
              }

              .card h3 {
                color: var(--accent-color);
                margin-bottom: 1rem;
                font-size: 1.5rem;
              }

              .card p {
                color: #aaaacc;
              }

              /* Code Example */
              .code-example {
                background: #000;
                border-radius: 8px;
                padding: 1.5rem;
                margin: 2rem 0;
                border-left: 4px solid var(--accent-color);
                font-family: 'Courier New', Courier, monospace;
                overflow-x: auto;
              }

              .code-example .keyword { color: #ff79c6; }
              .code-example .function { color: #8be9fd; }
              .code-example .string { color: #f1fa8c; }
              .code-example .comment { color: #6272a4; }

              /* Exchange Logos */
              .exchanges {
                text-align: center;
                margin-top: 4rem;
                padding: 2rem;
                background: rgba(255, 255, 255, 0.02);
                border-radius: 12px;
              }

              .exchanges h2 {
                margin-bottom: 2rem;
                color: var(--text-color);
              }

              .logo-grid {
                display: flex;
                justify-content: center;
                gap: 2rem;
                flex-wrap: wrap;
              }

              .logo {
                width: 80px;
                height: 80px;
                background: var(--card-bg);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                border: 1px solid rgba(255, 255, 255, 0.1);
                transition: all 0.3s ease;
                font-weight: bold;
                color: #555;
              }

              .logo:hover {
                border-color: var(--accent-color);
                box-shadow: 0 0 15px var(--accent-glow);
                color: var(--accent-color);
              }

              footer {
                text-align: center;
                padding: 2rem;
                margin-top: 4rem;
                border-top: 1px solid rgba(255, 255, 255, 0.1);
                color: #666;
              }

              @media (max-width: 768px) {
                h1 { font-size: 2.5rem; }
                .container { padding: 1rem; }
              }
            </style>
          </head>
          <body>
            <div class="container">
              <header>
                <h1>Dr. Manhattan</h1>
                <p class="subtitle">Quantum Trading Intelligence</p>

                <div class="install-box">
                  <span class="code">pip install dr-manhattan</span>
                  <button class="copy-btn" onclick="copyInstall()">Copy</button>
                </div>
              </header>

              <section class="features">
                <div class="card">
                  <h3>Quantum Analysis</h3>
                  <p>Advanced market analysis powered by quantum-inspired algorithms for superior prediction accuracy.</p>
                </div>
                <div class="card">
                  <h3>Real-time Execution</h3>
                  <p>Lightning-fast trade execution with minimal latency across multiple exchanges.</p>
                </div>
                <div class="card">
                  <h3>Risk Management</h3>
                  <p>Sophisticated risk assessment models to protect your portfolio in volatile markets.</p>
                </div>
              </section>

              <section>
                <h2 style="text-align: center; margin-bottom: 1rem;">Quick Start</h2>
                <div class="code-example">
                  <span class="keyword">from</span> dr_manhattan <span class="keyword">import</span> QuantumTrader<br><br>
                  <span class="comment"># Initialize the trader</span><br>
                  trader = <span class="function">QuantumTrader</span>(api_key=<span class="string">"your_key"</span>)<br><br>
                  <span class="comment"># Start analysis</span><br>
                  trader.<span class="function">analyze</span>(symbol=<span class="string">"BTC/USDT"</span>)
                </div>
              </section>

              <section class="exchanges">
                <h2>Supported Exchanges</h2>
                <div class="logo-grid">
                  <div class="logo">BIN</div>
                  <div class="logo">COIN</div>
                  <div class="logo">KRA</div>
                  <div class="logo">BYB</div>
                </div>
              </section>

              <footer>
                <p>&copy; 2024 Dr. Manhattan. All rights reserved.</p>
              </footer>
            </div>

            <script>
              function copyInstall() {
                navigator.clipboard.writeText('pip install dr-manhattan');
                const btn = document.querySelector('.copy-btn');
                const originalText = btn.innerText;
                btn.innerText = 'Copied!';
                setTimeout(() => {
                  btn.innerText = originalText;
                }, 2000);
              }
            </script>
          </body>
          </html>
          EOF

      - name: Setup Pages
        uses: actions/configure-pages@v4

      - name: Upload artifact
        uses: actions/upload-pages-artifact@v3
        with:
          path: 'docs'

  deploy:
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    runs-on: ubuntu-latest
    needs: build
    steps:
      - name: Deploy to GitHub Pages
        id: deployment
        uses: actions/deploy-pages@v4
